module chemical_table(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [3:0] m,\n    input wire [63:0] grid,\n    output reg [7:0] answer,\n    output reg done\n);\n\n    // Module parameters\n    localparam N = 8;\n    localparam M = 8;\n    localparam NM = 64;\n    localparam NODES = 16;\n\n    // State declarations\n    localparam [2:0] IDLE            = 3'd0;\n    localparam [2:0] INIT_DSU        = 3'd1;\n    localparam [2:0] PROCESS_CELLS   = 3'd2;\n    localparam [2:0] FIND_ROW        = 3'd3;\n    localparam [2:0] FIND_COL        = 3'd4;\n    localparam [2:0] MERGE           = 3'd5;\n    localparam [2:0] COUNT_COMPONENTS= 3'd6;\n    localparam [2:0] DONE_STATE      = 3'd7;\n\n    reg [2:0] state, next_state;\n    reg [5:0] current_cell;\n    reg [3:0] parent [0:15];    // 16 nodes, 4 bits each\n    reg [1:0] rank [0:15];      // 16 ranks, 2 bits each\n    reg [3:0] row_node, col_node;\n    reg [3:0] row_root, col_root;\n    reg [4:0] count_node;\n    reg [7:0] component_count;\n\n    wire [2:0] i = current_cell[5:3];  // i = cell / M (M=8)\n    wire [2:0] j = current_cell[2:0];  // j = cell % M\n    wire cell_valid = (i < n) && (j < m);\n    wire cell_data = grid[current_cell];\n\n    // Sequential state transitions\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            answer <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= INIT_DSU;\n                    end\n                end\n                \n                INIT_DSU: begin\n                    state <= PROCESS_CELLS;\n                end\n                \n                PROCESS_CELLS: begin\n                    if (current_cell >= NM) begin\n                        state <= COUNT_COMPONENTS;\n                    end else if (cell_valid && cell_data) begin\n                        state <= FIND_ROW;\n                    end\n                end\n                \n                FIND_ROW: state <= FIND_COL;\n                FIND_COL: state <= MERGE;\n                \n                MERGE: state <= PROCESS_CELLS;\n                \n                COUNT_COMPONENTS: begin\n                    if (count_node >= (n + m)) begin\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    state <= IDLE;\n                    done <= 1'b1;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // Combinational logic and data path\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_cell <= 6'd0;\n            answer <= 8'd0;\n            done <= 1'b0;\n            row_node <= 4'd0;\n            row_root <= 4'd0;\n            col_node <= 4'd0;\n            col_root <= 4'd0;\n            count_node <= 5'd0;\n            component_count <= 8'd0;\n            for (integer k = 0; k < 16; k = k + 1) begin\n                parent[k] <= k[3:0];\n                rank[k] <= 2'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        current_cell <= 6'd0;\n                    end\n                end\n                \n                INIT_DSU: begin\n                    for (integer k = 0; k < 16; k = k + 1) begin\n                        parent[k] <= k[3:0];\n                        rank[k] <= 2'd0;\n                    end\n                    current_cell <= 6'd0;\n                end\n                \n                PROCESS_CELLS: begin\n                    if (current_cell >= NM) begin\n                        count_node <= 5'd0;\n                        component_count <= 8'd0;\n                    end else if (cell_valid && cell_data) begin\n                        row_node <= i[3:0];\n                        col_node <= N + j[3:0];\n                    end else begin\n                        current_cell <= current_cell + 6'd1;\n                    end\n                end\n                \n                FIND_ROW: begin\n                    row_root <= parent[row_node];\n                    if (parent[row_node] != row_node) begin\n                        row_node <= parent[row_node];\n                    end\n                end\n                \n                FIND_COL: begin\n                    col_root <= parent[col_node];\n                    if (parent[col_node] != col_node) begin\n                        col_node <= parent[col_node];\n                    end\n                end\n                \n                MERGE: begin\n                    // Union by rank\n                    if (row_root != col_root) begin\n                        if (rank[row_root] > rank[col_root]) begin\n                            parent[col_root] <= row_root;\n                        end else if (rank[row_root] < rank[col_root]) begin\n                            parent[row_root] <= col_root;\n                        end else begin\n                            parent[col_root] <= row_root;\n                            rank[row_root] <= rank[row_root] + 2'd1;\n                        end\n                    end\n                    current_cell <= current_cell + 6'd1;\n                end\n                \n                COUNT_COMPONENTS: begin\n                    if (count_node < n) begin\n                        if (parent[count_node] == count_node[3:0]) begin\n                            component_count <= component_count + 8'd1;\n                        end\n                        count_node <= count_node + 5'd1;\n                    end else if (count_node < (n + m)) begin\n                        if (parent[N + count_node - n] == (N + count_node - n)[3:0]) begin\n                            component_count <= component_count + 8'd1;\n                        end\n                        count_node <= count_node + 5'd1;\n                    end\n\n                    if (count_node >= (n + m)) begin\n                        answer <= (component_count > 8'd1) ? (component_count - 8'd1) : 8'd0;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                end\n                \n                default: begin end\n            endcase\n        end\n    end\n\nendmodule